// One digest both sides read: Taifoon's public sale run and the key's standing, beside NEAR's own per-model consumption
// (GET /v1/admin/platform/model-revenue, external providers, last 24 h) when NEAR runs the admin read.
const s = $('Sale run').first().json; let k = {}; try { k = $('Key standing').first().json; } catch {}
let near = []; try { near = ($('GET /v1/admin/platform/model-revenue — NEAR runs this').first().json.data ?? []); } catch {}
const ours = near.filter((r) => r.provider_type === 'external');
const inference = (s.cells ?? []).filter((c) => /inference/.test(c.class ?? ''));
return [{ json: { date: new Date().toISOString().slice(0, 10),
  ledger: { sales: s.sales, events: s.events, sigma: s.sigma, invariant: s.invariant, reconcile: s.reconcile },
  inference_pairs: inference.map((c) => ({ venue_in: c.venue_in, venue_out: c.venue_out, stage: c.stage, outcomes: c.outcomes })),
  key: { balance_usdc: k.balance?.usdc ?? null, spent_usdc: k.balance?.spent_usdc ?? null, metered_today_grid: k.budgets?.metered_today_grid ?? null },
  near_external_last_24h: { models: ours.map((r) => ({ model: r.model_name, requests: r.requests, tokens: r.tokens, consumed_cost_usd: r.consumed_cost_usd })), consumed_cost_usd: ours.reduce((a, r) => a + (r.consumed_cost_usd ?? 0), 0) },
  rule: 'each answer is one sale on the key at the list price; NEAR reconciles its consumed cost for the Taifoon rows against the key spend and the sale run' } }];
